"""Module keeps the functionality for setting the static route for uplane_trace tracing
"""
import logging
import json
from taf.collectors.core.entities.managed_coam_cu_connection import ManagedCoamCUConnection

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CuStaticRouteSetter:
    """Class for setting the static route on the CU of a VRAN testline
    """

    def __init__(self, admin_params):
        """Construction of static route setter for CU

        :param admin_params: dictionary containing the connection details for the admin cli
        """
        self.admin = ManagedCoamCUConnection(cu_connection_params=admin_params)

    def _create_delta_file(self, dest_ip_addr, gateway):

        parameters = [{'parameterName': 'staticRoutes',
                       'value': [{"destIpAddr": dest_ip_addr,
                                  "destinationIpPrefixLength": "32",
                                  "gateway": gateway,
                                  "preference": "1"}],
                       'operation': 'create'}]

        return [{"distName": "MRBTS-1/TNLSVC-1/TNL-3/IPNO-1/IPRT-1",
                 "operation": "create",
                 "parameters": parameters}]

    def set_static_route(self, dest_ip_addr, gateway, timeout=120):
        """Sets the static route via admin cli for the collection of uplane_trace traces

        :param str dest_ip_addr: The destination address of the static route
        :param str gateway: The gateway ip address for the static route
        :param int timeout: Timeout in seconds for the call of the provisioning
        """
        try:
            self.admin.setup()

            if not self.is_static_route_set(destination_ip_addr=dest_ip_addr, gateway=gateway):
                delta_file = self._create_delta_file(dest_ip_addr=dest_ip_addr, gateway=gateway)
                result = self.admin.perform_delta_recommissioning(delta_file=json.dumps(delta_file), timeout=timeout)
                if result['status'] != 'success':
                    logger.error("Error in setting static route for uplane trace on CU %s" % result)

        except Exception as e:
            logger.error(f"Exception during static route commissioning: {e}")
        finally:
            self.admin.teardown()

    def get_configured_static_routes(self):
        """Uses admin cli call "get_parameters" to determine all currently set static routes
        """
        iprt_parameters = self.admin.get_parameters(dist_name="MRBTS-1/TNLSVC-1/TNL-3/IPNO-1/IPRT-1")
        static_routes = []
        for param in iprt_parameters.parameters:
            if param.complex_parameter.name == 'staticRoutes':
                for complex_param in param.complex_parameter.value:
                    route = {}
                    for struct in complex_param.structure_parameters:
                        route[struct.simple_parameter.name] = struct.simple_parameter.value
                    static_routes.append(route)
        return static_routes

    def is_static_route_set(self, destination_ip_addr, gateway):
        """Checks, if there is already a route defined in CU for the given destination_ip_address and gatewa

        :param str destination_ip_addr: The destination address of the static route
        :param str gateway: The gateway ip address for the static route
        """
        current_routes = self.get_configured_static_routes()

        return any(route["destIpAddr"] == destination_ip_addr and route["gateway"] == gateway
                   for route in current_routes)
